import hmac
import hashlib
import time
import json
import os
from flask import Flask, request, jsonify, abort
from functools import wraps
import threading

app = Flask(__name__)

# Rate limiter using token bucket algorithm
class RateLimiter:
    def __init__(self, max_tokens=100, refill_rate=10):
        self._lock = threading.Lock()
        self._buckets = {}
        self._max_tokens = max_tokens
        self._refill_rate = refill_rate

    def _get_bucket(self, key):
        now = int(time.time())
        if key not in self._buckets:
            self._buckets[key] = {'tokens': self._max_tokens, 'last_refill': now}
        bucket = self._buckets[key]
        # Calculate tokens to add based on elapsed time
        elapsed = now - bucket['last_refill']
        # Refill tokens
        new_tokens = bucket['tokens'] + elapsed * self._refill_rate
        bucket['tokens'] = min(new_tokens, self._max_tokens)
        bucket['last_refill'] = now
        return bucket

    def consume(self, key, tokens=1):
        with self._lock:
            bucket = self._get_bucket(key)
            if bucket['tokens'] >= tokens:
                bucket['tokens'] -= tokens
                return True
            return False

    def get_remaining(self, key):
        with self._lock:
            bucket = self._get_bucket(key)
            return bucket['tokens']

rate_limiter = RateLimiter(max_tokens=100, refill_rate=10)

def get_webhook_secret():
    """Retrieve webhook secret from environment."""
    secret = os.environ.get('WEBHOOK_SECRET', '')
    if not secret:
        raise RuntimeError("WEBHOOK_SECRET must be configured")
    return secret

def verify_webhook_signature(payload_body, signature_header):
    """Verify GitHub webhook signature using HMAC-SHA256."""
    if not signature_header:
        return False

    try:
        secret = get_webhook_secret()
    except RuntimeError:
        return False

    if not signature_header.startswith('sha256='):
        return False

    received_sig = signature_header[7:]  # Strip 'sha256=' prefix

    # Compute expected signature
    expected_sig = hmac.new(
        secret.encode('utf-8'),
        payload_body,
        hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(expected_sig, received_sig)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        # Check rate limit first
        client_ip = request.remote_addr

        if not rate_limiter.consume(client_ip):
            return jsonify({'error': 'Rate limit exceeded'}), 429

        # Verify webhook signature
        signature = request.headers.get('X-Hub-Signature-256')
        if not verify_webhook_signature(request.get_data(), signature):
            return jsonify({'error': 'Invalid signature'}), 401

        return f(*args, **kwargs)
    return decorated

class DeploymentManager:
    """Manages deployment pipeline stages."""

    def __init__(self):
        self._deployments = {}
        self._lock = threading.Lock()

    def create_deployment(self, repo, branch, commit_sha, config):
        """Create a new deployment record."""
        deployment_id = f"{repo}-{branch}-{commit_sha[:8]}"

        with self._lock:
            self._deployments[deployment_id] = {
                'id': deployment_id,
                'repo': repo,
                'branch': branch,
                'commit': commit_sha,
                'status': 'pending',
                'stages': config.get('stages', []),
                'current_stage': 0,
                'created_at': time.time()
            }

        return deployment_id

    def advance_stage(self, deployment_id):
        """Advance deployment to next stage."""
        with self._lock:
            dep = self._deployments.get(deployment_id)
            if not dep:
                return None

            if dep['current_stage'] < len(dep['stages']) - 1:
                dep['current_stage'] += 1
                dep['status'] = 'in_progress'
            else:
                dep['status'] = 'completed'

            return dep

    def get_deployment(self, deployment_id):
        with self._lock:
            return self._deployments.get(deployment_id)

deployment_manager = DeploymentManager()

def parse_webhook_payload(data):
    """Parse and validate webhook payload."""
    try:
        payload = json.loads(data)
    except (json.JSONDecodeError, TypeError):
        return None

    # Extract required fields
    ref = payload.get('ref', '')
    if not ref.startswith('refs/heads/'):
        return None

    branch = ref[11:]  # Strip 'refs/heads/'

    commit_sha = payload.get('after') or payload.get('head_commit', {}).get('id')
    if not commit_sha:
        return None

    repo = payload.get('repository', {}).get('full_name')
    if not repo:
        return None

    return {
        'branch': branch,
        'commit_sha': commit_sha,
        'repository': repo,
        'pusher': payload.get('pusher', {}).get('name', 'unknown')
    }

def get_deployment_config(repo, branch):
    """Get deployment configuration for a repo/branch."""
    # In production, this would read from a config file
    allowed_repos = ['myorg/myapp', 'myorg/service-api']

    if repo not in allowed_repos:
        return None

    if branch == 'main':
        return {
            'stages': ['build', 'test', 'staging', 'production'],
            'auto_advance': True,
            'notifications': True
        }
    elif branch.startswith('release/'):
        return {
            'stages': ['build', 'test', 'staging'],
            'auto_advance': False,
            'notifications': True
        }

    return None

@app.route('/webhook', methods=['POST'])
@require_auth
def handle_webhook():
    """Handle incoming webhook events."""
    payload = parse_webhook_payload(request.get_data())
    if not payload:
        return jsonify({'error': 'Invalid payload'}), 400

    config = get_deployment_config(payload['repository'], payload['branch'])
    if not config:
        return jsonify({'status': 'ignored', 'reason': 'no matching config'}), 200

    deployment_id = deployment_manager.create_deployment(
        payload['repository'],
        payload['branch'],
        payload['commit_sha'],
        config
    )

    # Auto-advance if configured
    if config.get('auto_advance'):
        deployment_manager.advance_stage(deployment_id)

    return jsonify({
        'status': 'accepted',
        'deployment_id': deployment_id
    }), 202

@app.route('/deployments/<deployment_id>', methods=['GET'])
def get_deployment(deployment_id):
    """Get deployment status."""
    dep = deployment_manager.get_deployment(deployment_id)
    if not dep:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dep), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
